<script setup lang="ts">
import {ref,computed,watch,onMounted} from 'vue';import {campaignDates} from '../campaign-scheduling';import {campaignApi} from '../campaign-api';import Modal from './Modal.vue';import type {WorkTab} from '../stores';
const props=defineProps<{kind:'trips'|'checklist';campaign:any;stores:any[];canEdit:boolean;tab:WorkTab}>();
const rows=ref<any[]>([]),loading=ref(false),error=ref(''),message=ref(''),form=ref<any>(null),baseline=ref(''),discard=ref(false),deleting=ref<any>(null);
const calendar=ref(props.kind==='trips'),dragged=ref<number|null>(null);
const dates=computed(()=>campaignDates(props.campaign.start_date,props.campaign.end_date));
const title=computed(()=>props.kind==='trips'?'設備車次':'前置工作');
const fields=computed(()=>props.kind==='trips'?[['set_number','設備套次','number'],['trip_date','運送日期','date'],['from_location','起點','text'],['to_location','目的地','text'],['notes','備註','textarea']]:[['task_name','工作事項','text'],['assigned_person','安排人員','text'],['deadline','完成期限','date'],['notes','備註','textarea']]);
watch(()=>JSON.stringify(form.value),value=>{props.tab.dirty=!!form.value&&value!==baseline.value;},{flush:'sync'});props.tab.submitOnly=true;
async function load(){loading.value=true;error.value='';try{rows.value=(await campaignApi(props.kind,{campaign_id:props.campaign.id})).data||[];}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
function edit(row?:any){form.value=row?{...row}:props.kind==='trips'?{set_number:1,trip_date:props.campaign.start_date,from_location:'',to_location:'',notes:''}:{task_name:'',assigned_person:'',deadline:'',notes:'',item_order:rows.value.length};baseline.value=JSON.stringify(form.value);props.tab.dirty=false;}
function close(){if(props.tab.busy)return;if(props.tab.dirty)discard.value=true;else form.value=null;}
async function save(){props.tab.busy=true;error.value='';try{await campaignApi(props.kind,{},form.value.id?'PUT':'POST',{...form.value,deadline:form.value.deadline||null,campaign_id:props.campaign.id});form.value=null;message.value='已儲存'+title.value;await load();}catch(e){error.value=(e as Error).message;}finally{props.tab.busy=false;}}
async function remove(){props.tab.busy=true;error.value='';try{await campaignApi(props.kind,{id:deleting.value.id},'DELETE');deleting.value=null;await load();message.value='已刪除'+title.value;}catch(e){error.value=(e as Error).message;}finally{props.tab.busy=false;}}
async function move(index:number,offset:number){const next=[...rows.value],[a]=next.splice(index,1);next.splice(index+offset,0,a);props.tab.busy=true;error.value='';try{await campaignApi('checklist-order',{},'PUT',{campaign_id:props.campaign.id,ids:next.map(r=>r.id)});await load();}catch(e){error.value=(e as Error).message;}finally{props.tab.busy=false;}}
onMounted(load);
</script>
<template><div class="toolbar"><h2>{{title}}</h2><button v-if="kind==='trips'" @click="calendar=!calendar">{{calendar?'只看車次列表':'顯示車次日曆'}}</button><button :disabled="loading||tab.busy" @click="load">重新整理</button><button v-if="canEdit" :disabled="loading||tab.busy" class="primary" @click="edit()">新增{{title}}</button></div><p v-if="error" role="alert" class="notice error">{{error}}</p><p v-if="message" role="status" class="notice">{{message}}</p><p v-if="loading">讀取中…</p><div v-if="kind==='trips'&&calendar&&!loading" class="trip-calendar"><div v-for="day in dates" :key="day"><strong>{{day}}</strong><button v-if="canEdit" :disabled="tab.busy" @click="edit();form.trip_date=day">新增車次</button><button v-for="r in rows.filter(r=>r.trip_date===day)" :disabled="!canEdit||tab.busy" @click="edit(r)">第 {{r.set_number}} 套 · {{r.from_location}} → {{r.to_location}}</button></div></div><div v-if="!loading" class="module-table"><table><thead><tr><th v-for="f in fields">{{f[1]}}</th><th>操作</th></tr></thead><tbody><tr v-for="(r,i) in rows" :key="r.id" :draggable="kind==='checklist'&&canEdit&&!tab.busy" @dragstart="dragged=i" @dragover.prevent @drop.prevent="dragged!==null&&dragged!==i?move(dragged,i-dragged):undefined;dragged=null"><td v-for="f in fields">{{r[f[0]]||'—'}}</td><td><template v-if="canEdit"><button @click="edit(r)">編輯</button><button class="danger" @click="deleting=r">刪除</button><template v-if="kind==='checklist'"><button :disabled="i===0||tab.busy" @click="move(i,-1)" :aria-label="'上移 '+r.task_name">上移</button><button :disabled="i===rows.length-1||tab.busy" @click="move(i,1)" :aria-label="'下移 '+r.task_name">下移</button></template></template><span v-else>唯讀</span></td></tr></tbody></table><p v-if="!rows.length">尚無{{title}}。</p></div>
<Modal v-if="form" :title="(form.id?'編輯':'新增')+title" :busy="tab.busy" @cancel="close"><form @submit.prevent="save"><fieldset :disabled="tab.busy"><label v-for="f in fields">{{f[1]}}<textarea v-if="f[2]==='textarea'" v-model="form[f[0]]" rows="3"/><input v-else-if="f[2]==='number'" type="number" min="1" max="5" v-model.number="form[f[0]]" required><input v-else :type="f[2]" v-model="form[f[0]]" :list="f[0].endsWith('location')?'campaign-locations':undefined" :required="['task_name','trip_date','from_location','to_location'].includes(f[0])"></label><datalist id="campaign-locations"><option value="林森街倉庫"/><option value="車上"/><option v-for="s in stores" :value="s.store_name"/></datalist></fieldset><p v-if="error" role="alert" class="notice error">{{error}}</p><div class="dialog-actions"><button type="button" :disabled="tab.busy" @click="close">取消</button><button class="primary" :disabled="tab.busy">{{tab.busy?'儲存中…':'儲存'}}</button></div></form></Modal>
<Modal v-if="discard" title="放棄修改？" @cancel="discard=false"><p>尚未儲存的內容將被放棄。</p><div class="dialog-actions"><button @click="discard=false">繼續編輯</button><button class="danger" @click="form=null;discard=false">放棄修改</button></div></Modal>
<Modal v-if="deleting" :title="'刪除'+title+'？'" :busy="tab.busy" @cancel="deleting=null"><p>{{deleting.task_name||deleting.trip_date+' '+deleting.from_location+' → '+deleting.to_location}}，刪除後無法復原{{kind==='checklist'?'，相關門市完成紀錄也會移除':''}}。</p><p v-if="error" role="alert">{{error}}</p><div class="dialog-actions"><button :disabled="tab.busy" @click="deleting=null">取消</button><button class="danger" :disabled="tab.busy" @click="remove">確認刪除</button></div></Modal>
</template>
<style scoped>.trip-calendar{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:6px;margin:20px 0}.trip-calendar>div{border:1px solid var(--line);padding:8px;min-width:0}.trip-calendar strong{display:block;font-size:12px}.trip-calendar button{display:block;width:100%;white-space:normal;font-size:12px;padding:6px;margin:6px 0}@media(max-width:800px){.trip-calendar{grid-template-columns:repeat(2,minmax(0,1fr))}}.toolbar{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.toolbar h2{font-size:18px;margin-right:auto}fieldset{border:0;padding:0}label{display:grid;gap:8px;margin:16px 0}td{white-space:pre-wrap;vertical-align:top}td button{margin:3px}input,textarea{width:100%}</style>
